function safe(name) {
  try { return $(name).first().json || {}; } catch (e) { return { _error: true, _message: String(e.message || e) }; }
}

const driftResp = safe('Get Configuration Drift');
const prevRows = (() => {
  try {
    return $('Get Previous States').all().map(i => i.json);
  } catch (e) {
    return [];
  }
})();

const now = new Date().toISOString();
const sevMap = { low: 'info', medium: 'warning', high: 'error', critical: 'critical' };

if (driftResp._error || !driftResp.summary) {
  return [{
    json: {
      skip_persist: true,
      should_emit: false,
      overall_status: 'degraded',
      error: driftResp._message || driftResp.detail || 'configuration_drift_unavailable',
      events: [],
      persist_rows: [],
    },
  }];
}

if (driftResp.baseline_status === 'missing' || driftResp.drift_type === 'baseline_missing') {
  const event = {
    source: 'configuration_drift_guardian',
    severity: 'warning',
    component: 'configuration',
    event: 'configuration_baseline_missing',
    status: 'attention',
    timestamp: now,
    message: 'Baseline de configuração ausente. Nenhuma alteração automática foi feita.',
    details: {
      baseline_status: driftResp.baseline_status,
      advisory_only: true,
      auto_repair: false,
    },
    requires_attention: true,
    suggested_action: 'approve_new_baseline',
  };
  return [{
    json: {
      skip_persist: false,
      should_emit: true,
      overall_status: 'degraded',
      events: [event],
      persist_rows: [],
      meta: { last_overall_status: 'degraded', last_summary: driftResp.summary || {} },
    },
  }];
}

const prevBy = {};
for (const r of prevRows) {
  if (r && r.component) prevBy[r.component] = r;
}

const persist_rows = [];
const events = [];
const items = Array.isArray(driftResp.items) ? driftResp.items : [];

for (const item of items) {
  const component = item.component;
  const prev = prevBy[component] || null;
  const status = item.status || 'unknown';
  const fpAfter = item.fingerprint_after || null;
  const fpBefore = item.fingerprint_before || null;
  const risk = item.risk || null;
  const driftType = item.drift_type || null;

  let emit = null;
  let resolved_at = null;
  let first_seen_at = prev && prev.first_seen_at ? prev.first_seen_at : null;

  if (status === 'match') {
    if (prev && prev.status === 'drift') {
      emit = 'configuration_drift_resolved';
      resolved_at = now;
    }
  } else if (status === 'drift') {
    const sameFp = prev && prev.current_fingerprint && prev.current_fingerprint === fpAfter && prev.status === 'drift';
    const riskEscalated = prev && prev.risk && risk && prev.risk !== risk && (
      ['low','medium','high','critical'].indexOf(risk) > ['low','medium','high','critical'].indexOf(prev.risk)
    );
    if (!prev || prev.status !== 'drift') {
      emit = item.should_emit_event || 'configuration_drift_detected';
      first_seen_at = now;
    } else if (!sameFp || riskEscalated) {
      emit = item.should_emit_event || 'configuration_drift_detected';
      if (!first_seen_at) first_seen_at = now;
    } else {
      emit = null; // dedup silence
      if (!first_seen_at) first_seen_at = prev.first_seen_at || now;
    }
  } else if (status === 'unknown' && driftType === 'collector_partial') {
    // no spam for persistent UFW partial
    emit = null;
  }

  const details = {
    change_type: item.change_type,
    before_summary: item.before_summary,
    after_summary: item.after_summary,
    recommendation: item.recommendation,
    drift_type: driftType,
    risk,
    advisory_only: true,
    auto_repair: false,
  };

  persist_rows.push({
    component,
    baseline_fingerprint: fpBefore,
    current_fingerprint: fpAfter,
    drift_type: driftType,
    risk,
    status,
    first_seen_at: first_seen_at,
    last_seen_at: now,
    resolved_at,
    details,
    emit,
  });

  if (emit) {
    const severity = sevMap[risk || 'medium'] || 'warning';
    let message;
    if (emit === 'configuration_drift_resolved') {
      message = `Configuração de ${component} voltou a corresponder ao baseline. Nenhuma alteração automática foi feita pelo Guardian.`;
    } else if (emit === 'security_configuration_drift') {
      message = `Detectei uma mudança de configuração de segurança no OMEAB (${component}). Nenhuma configuração foi modificada automaticamente.`;
    } else if (emit === 'runtime_configuration_drift') {
      message = `Detectei drift de configuração em runtime (${component}). Investigar imagem/porta efetiva vs Compose.`;
    } else {
      message = `Detectei uma mudança de configuração no OMEAB (${component}). Nenhuma configuração foi modificada automaticamente.`;
    }
    events.push({
      source: 'configuration_drift_guardian',
      severity: emit === 'configuration_drift_resolved' ? 'info' : severity,
      component: 'configuration',
      event: emit,
      status: emit === 'configuration_drift_resolved' ? 'recovered' : (risk === 'critical' || risk === 'high' ? 'degraded' : 'attention'),
      timestamp: now,
      message,
      details: {
        monitored_component: component,
        change_type: item.change_type,
        before_summary: item.before_summary,
        after_summary: item.after_summary,
        risk,
        recommendation: item.recommendation,
        fingerprint_before: fpBefore,
        fingerprint_after: fpAfter,
        advisory_only: true,
        auto_repair: false,
      },
      requires_attention: emit !== 'configuration_drift_resolved',
      suggested_action: item.recommendation || 'review_change',
    });
  }
}

return [{
  json: {
    skip_persist: false,
    should_emit: events.length > 0,
    overall_status: driftResp.overall_status,
    summary: driftResp.summary,
    partial: driftResp.partial || [],
    snapshot_execution_time_ms: driftResp.snapshot_execution_time_ms,
    persist_rows,
    events,
    meta: {
      last_overall_status: driftResp.overall_status,
      last_summary: driftResp.summary || {},
    },
  },
}];

