={{
(() => {
  if ($json.skip_persist) return 'SELECT 1 AS skipped;';
  const esc = (v) => String(v ?? '').replace(/'/g, "''");
  const rows = $json.persist_rows || [];
  if (!rows.length) return 'SELECT 1 AS no_rows;';
  const parts = rows.map((r) => {
    const details = JSON.stringify(r.details || {}).replace(/'/g, "''");
    const fs = r.first_seen_at ? `'${esc(r.first_seen_at)}'::timestamptz` : 'NULL';
    const rs = r.resolved_at ? `'${esc(r.resolved_at)}'::timestamptz` : 'NULL';
    return `INSERT INTO configuration_drift_state (
      component, baseline_fingerprint, current_fingerprint, drift_type, risk, status,
      first_seen_at, last_seen_at, resolved_at, details
    ) VALUES (
      '${esc(r.component)}',
      ${r.baseline_fingerprint ? `'${esc(r.baseline_fingerprint)}'` : 'NULL'},
      ${r.current_fingerprint ? `'${esc(r.current_fingerprint)}'` : 'NULL'},
      ${r.drift_type ? `'${esc(r.drift_type)}'` : 'NULL'},
      ${r.risk ? `'${esc(r.risk)}'` : 'NULL'},
      '${esc(r.status)}',
      ${fs},
      '${esc(r.last_seen_at)}'::timestamptz,
      ${rs},
      '${details}'::jsonb
    )
    ON CONFLICT (component) DO UPDATE SET
      baseline_fingerprint = EXCLUDED.baseline_fingerprint,
      current_fingerprint = EXCLUDED.current_fingerprint,
      drift_type = EXCLUDED.drift_type,
      risk = EXCLUDED.risk,
      status = EXCLUDED.status,
      first_seen_at = COALESCE(configuration_drift_state.first_seen_at, EXCLUDED.first_seen_at),
      last_seen_at = EXCLUDED.last_seen_at,
      resolved_at = EXCLUDED.resolved_at,
      details = EXCLUDED.details`;
  });
  return parts.join(';\n') + ';';
})()
}}

